            background-size: cover;
            background-position: center;
            height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            margin-top: 70px;
        }

        .hero-content h1 {
            font-size: 4rem;
            margin-bottom: 1rem;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
        }

        .hero-content p {
            font-size: 1.5rem;
            margin-bottom: 2rem;
        }

        .btn {
            display: inline-block;
            padding: 1rem 2rem;
            background-color: #ff6b35;
            color: #ffffff;
            text-decoration: none;
            border-radius: 5px;
            transition: background-color 0.3s;
            font-weight: bold;
        }

        .btn:hover {
            background-color: #ff5722;
        }

        /* Section Styles */
        section {
            padding: 4rem 2rem;
            max-width: 1200px;
            margin: 0 auto;
        }

        h2 {
            font-size: 2.5rem;
            margin-bottom: 2rem;
            color: #ff6b35;
            text-align: center;
        }

        /* Features Grid */
        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
            margin-top: 2rem;
        }

        .feature-card {
            background-color: #1a1a1a;
            padding: 2rem;
            border-radius: 10px;
            text-align: center;
            transition: transform 0.3s;
        }

        .feature-card:hover {
            transform: translateY(-5px);
        }

        .feature-icon {
            font-size: 3rem;
            margin-bottom: 1rem;
        }

        /* Weapons Section */
        .weapons-container {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 1.5rem;
            margin-top: 2rem;
        }

        .weapon-card {
            background-color: #1a1a1a;
            border-radius: 8px;
            padding: 1.5rem;
            text-align: center;
            border: 2px solid transparent;
            transition: border-color 0.3s;
        }

        .weapon-card:hover {
            border-color: #ff6b35;
        }

        .weapon-name {
            font-size: 1.2rem;
            margin: 1rem 0;
            color: #ff6b35;
        }

        .weapon-stats {
            font-size: 0.9rem;
            color: #aaa;
        }

        /* Maps Section */
        .maps-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
            margin-top: 2rem;
        }

        .map-card {
            background-color: #1a1a1a;
            border-radius: 8px;
            overflow: hidden;
            transition: transform 0.3s;
        }

        .map-card:hover {
            transform: scale(1.05);
        }

        .map-image {
            width: 100%;
            height: 200px;
            background-color: #333;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 3rem;
            color: #555;
        }

        .map-info {
            padding: 1rem;
        }

        .map-name {
            font-size: 1.3rem;
            color: #ff6b35;
            margin-bottom: 0.5rem;
        }

        /* News Section */
        .news-container {
            display: grid;
            gap: 1.5rem;
            margin-top: 2rem;
        }

        .news-item {
            background-color: #1a1a1a;
            padding: 1.5rem;
            border-radius: 8px;
            display: flex;
            gap: 1.5rem;
            align-items: center;
        }

        .news-date {
            color: #ff6b35;
            font-weight: bold;
            min-width: 100px;
        }

        .news-content h3 {
            margin-bottom: 0.5rem;
        }

        /* Footer */
        footer {
            background-color: #1a1a1a;
            text-align: center;
            padding: 2rem 0;
            margin-top: 4rem;
        }

        .social-links {
            display: flex;
            justify-content: center;
            gap: 2rem;
            margin-top: 1rem;
        }

        .social-links a {
            color: #ffffff;
            font-size: 1.5rem;
            transition: color 0.3s;
        }

        .social-links a:hover {
            color: #ff6b35;
        }

        /* Responsive */
        @media (max-width: 768px) {
            .nav-links {
                display: none;
            }

            .hero-content h1 {
                font-size: 2.5rem;
            }

            .hero-content p {
                font-size: 1.2rem;
            }
        }
    </style>
</head>
<body>
    <!-- Header -->
    <header>
        <nav>
            <a href="#" class="logo">CS:GO HUB</a>
            <ul class="nav-links">
                <li><a href="#home">Home</a></li>
                <li><a href="#weapons">Weapons</a></li>
                <li><a href="#maps">Maps</a></li>
                <li><a href="#news">News</a></li>
                <li><a href="#guides">Guides</a></li>
            </ul>
        </nav>
    </header>

