        <div class="features-grid">
            <div class="feature-card">
                <div class="feature-icon">🎯</div>
                <h3>Weapon Guides</h3>
                <p>Detailed information about every weapon in CS:GO, including stats, spray patterns, and tips.</p>
            </div>
            <div class="feature-card">
                <div class="feature-icon">🗺️</div>
                <h3>Map Callouts</h3>
                <p>Learn all the map callouts and strategic positions for competitive play.</p>
            </div>
            <div class="feature-card">
                <div class="feature-icon">📊</div>
                <h3>Stats Tracking</h3>
                <p>Track your performance and improve your gameplay with detailed statistics.</p>
            </div>
        </div>
