                <div class="weapon-icon">🔫</div>
                <h3 class="weapon-name">M4A4</h3>
                <p class="weapon-stats">Damage: 33 | Fire Rate: 666 RPM | Price: $3100</p>
            </div>
            <div class="weapon-card">
                <div class="weapon-icon">🔫</div>
                <h3 class="weapon-name">AWP</h3>
                <p class="weapon-stats">Damage: 115 | Fire Rate: 41 RPM | Price: $4750</p>
