                <div class="map-image">🗺️</div>
                <div class="map-info">
                    <h3 class="map-name">Inferno</h3>
                    <p>Narrow corridors and chokepoints make this map perfect for tactical gameplay.</p>
                </div>
            </div>
        </div>
    </section>

